package com.az.scicalc;

import java.util.*;
import java.util.regex.Matcher;
import org.json.*;

/** Keypad driven base, table and coefficient workspaces. */
final class ModeWorkflows {
 final MainActivity app;private String baseline="",flow="",inequality="";private int step,degree,unknowns;
 private String[] tableValues=new String[5];
 ModeWorkflows(MainActivity app){this.app=app;}
 JSONObject savePage(){JSONObject j=new JSONObject();try{j.put("baseline",baseline).put("flow",flow).put("inequality",inequality).put("step",step).put("degree",degree).put("unknowns",unknowns).put("tableValues",new JSONArray(Arrays.asList(tableValues)));}catch(Exception ignored){}return j;}
 void restorePage(JSONObject j){if(j==null)return;baseline=j.optString("baseline");flow=j.optString("flow");inequality=j.optString("inequality");step=Math.max(0,Math.min(4,j.optInt("step")));degree=j.optInt("degree");unknowns=j.optInt("unknowns");JSONArray a=j.optJSONArray("tableValues");if(a!=null)for(int i=0;i<Math.min(5,a.length());i++)tableValues[i]=a.optString(i);}
 void end(){if(!flow.isEmpty()){if(app.view.gridActive&&(flow.equals("poly")||flow.equals("system"))){if(app.formula.complete())app.view.grid[app.view.gridRow][app.view.gridCol]=app.formula.source(1);app.workbench.saveGrid();app.view.gridActive=false;}app.formula.restore(baseline);flow="";}app.view.workflowStep=-1;app.view.workflowCaption="";app.view.baseMode=false;app.view.invalidate();}
 void begin(String type){end();if(app.view.gridActive)app.workbench.finishGrid();baseline=app.formula.save();flow=type;app.formula.clear();app.view.result="";app.exact="";app.view.second=false;app.calculator();}
 void bases(){begin("base");app.view.mode="BASE";app.view.baseMode=true;app.view.baseRadix=app.prefs.getInt("baseRadix",10);app.view.baseBits=app.prefs.getInt("baseBits",32);app.view.invalidate();}
 String baseSource(){return app.formula.source(1).replace("*","×").replace("××","**");}
 long baseValue(){return narrow(BaseExpression.evaluate(baseSource(),app.view.baseRadix,app.view.baseBits));}
 String baseFormat(long value,int radix){if(radix!=10&&app.view.baseBits<64)value&=(1L<<app.view.baseBits)-1;return BaseExpression.format(value,radix);}
 long narrow(long value){int bits=app.view.baseBits;return bits==64?value:value<<(64-bits)>>(64-bits);}
 void previewBase(){if(!app.prefs.getBoolean("autoPreview",true)||app.formula.empty())return;try{app.view.result=baseFormat(baseValue(),app.view.baseRadix);app.view.invalidate();}catch(Exception ignored){}}
 void baseCalculate(){try{long n=baseValue();String display=baseFormat(n,app.view.baseRadix);record("基数计算",new String[]{"表达式","进制","位宽"},new String[]{baseSource(),""+app.view.baseRadix,""+app.view.baseBits},""+n,display);app.view.addTape(app.formula.save(),""+n,display);app.formula.clear();app.save();app.view.invalidate();}catch(Exception e){app.error(e.getMessage());}}
 void table(){begin("table");app.view.mode="TABLE";String[] keys={"tableF","tableG","tableLo","tableHi","tableStep"},defaults={"","","0","5","1"};for(int i=0;i<5;i++)tableValues[i]=app.prefs.getString(keys[i],defaults[i]);step=0;loadStep();}
 void loadStep(){app.formula.clear();app.formula.insertExpression(tableValues[step]);app.formula.root.defaultValue=true;app.view.workflowStep=step;app.view.workflowCaption=new String[]{"f(x)=","g(x)=","起始值=","终止值=","步长="}[step];app.changed();}
 void tableNext(){if(step!=1&&(app.formula.empty()||!app.formula.complete())){app.error("请填写完整表达式");return;}tableValues[step]=app.formula.source(app.angleMode);if(step<4){step++;loadStep();return;}
  java.util.function.Function<String,String> resolve=app.varsForJob();String format=app.prefs.getString("numberFormat","normal");int digits=app.prefs.getInt("digits",11);boolean scientific=app.prefs.getBoolean("scientificE",false);
  app.task(()->{double lo=app.engine.value(tableValues[2]),hi=app.engine.value(tableValues[3]),inc=app.engine.value(tableValues[4]),count=(hi-lo)/inc;if(inc==0||!Double.isFinite(count)||count<0||count>199)throw new IllegalArgumentException("步长须指向终点，最多 200 行");String[][] values=new String[(int)Math.floor(count+1e-10)+1][tableValues[1].isEmpty()?2:3];JSONArray rows=new JSONArray();for(int r=0;r<values.length;r++){double x=lo+r*inc;values[r][0]=Double.toString(x);for(int c=1;c<values[r].length;c++){String source=resolve.apply(tableValues[c-1]).replaceAll("\\bx\\b",Matcher.quoteReplacement("("+x+")"));values[r][c]=ResultFormat.scientific(ResultFormat.format(app.engine.evaluate(source,true,digits),format,digits),scientific);}rows.put(new JSONArray(Arrays.asList(values[r])));}return rows.toString();},packed->{String[] keys={"tableF","tableG","tableLo","tableHi","tableStep"};android.content.SharedPreferences.Editor prefs=app.prefs.edit();for(int i=0;i<5;i++)prefs.putString(keys[i],tableValues[i]);prefs.apply();try{JSONArray rows=new JSONArray(packed);String[][] values=new String[rows.length()][];for(int r=0;r<values.length;r++){JSONArray row=rows.getJSONArray(r);values[r]=new String[row.length()];for(int c=0;c<values[r].length;c++)values[r][c]=row.getString(c);}app.view.workflowStep=-1;flow="";app.formula.restore(baseline);app.workbench.openGrid("tableResults","TABLE","table",values,values[0].length==2?new String[]{"X","f(x)"}:new String[]{"X","f(x)","g(x)"});}catch(Exception e){app.error(e.getMessage());}});
 }
 void polynomial(int degree,String inequality){begin("poly");this.degree=degree;this.inequality=inequality==null?"":inequality;app.view.mode="SOLVE";String[] headers=new String[degree+1];for(int c=0;c<=degree;c++)headers[c]=(char)('a'+c)+(degree-c==0?"":degree-c==1?"x":"x"+superscript(degree-c));app.workbench.openGrid("coefficients:"+degree+this.inequality,"POLY","poly",app.workbench.loadGrid("coefficients:"+degree+this.inequality,1,degree+1,"0"),headers);app.view.mode="SOLVE";app.view.coefficientTitle=headers[0]+"+"+headers[1]+"+… "+(this.inequality.isEmpty()?"=":this.inequality)+" 0";if(degree==2)app.view.coefficientTitle="ax²+bx+c "+(this.inequality.isEmpty()?"=":this.inequality)+" 0";app.view.invalidate();}
 void system(int n){begin("system");unknowns=n;app.view.mode="SOLVE";String[] variables={"x","y","z","t"},headers=new String[n+1];for(int c=0;c<n;c++)headers[c]=(char)('a'+c)+variables[c];headers[n]="="+(char)('a'+n);app.workbench.openGrid("coefficients:system"+n,"SYSTEM","system",app.workbench.loadGrid("coefficients:system"+n,n,n+1,"0"),headers);app.view.mode="SOLVE";app.view.coefficientTitle="解"+n+"元方程组";app.view.invalidate();}
 static String superscript(int n){String s=""+n,b="";for(char c:s.toCharArray())b+="⁰¹²³⁴⁵⁶⁷⁸⁹".charAt(c-'0');return b;}
 boolean reopen(JSONObject record){String kind=record.optString("workspaceKind");if(kind.isEmpty())return false;if(kind.equals("base")){bases();JSONArray values=record.optJSONArray("toolValues");if(values!=null){app.view.baseRadix=Integer.parseInt(values.optString(1,"10"));app.view.baseBits=Integer.parseInt(values.optString(2,"32"));app.formula.text(values.optString(0));app.changed();}return true;}if(kind.equals("poly"))polynomial(record.optInt("degree",2),record.optString("inequality"));else if(kind.equals("system"))system(record.optInt("unknowns",2));else return false;try{JSONArray rows=record.getJSONArray("workspaceData");for(int r=0;r<Math.min(rows.length(),app.view.grid.length);r++)for(int c=0;c<Math.min(rows.getJSONArray(r).length(),app.view.grid[r].length);c++)app.view.grid[r][c]=rows.getJSONArray(r).getString(c);app.workbench.saveGrid();app.workbench.cell(0,0);}catch(Exception ignored){}return true;}
 void solveCoefficients(){app.workbench.commit(()->{String[][] values=app.view.grid;String expression;ArrayList<String> labels=new ArrayList<>(),inputs=new ArrayList<>();String title;
   if(flow.equals("poly")){StringBuilder poly=new StringBuilder();for(int c=0;c<=degree;c++){if(c>0)poly.append('+');poly.append('(').append(values[0][c]).append(")*x^").append(degree-c);labels.add("系数 "+(char)('a'+c));inputs.add(values[0][c]);}expression=(inequality.isEmpty()?"Solve(":"Reduce(")+poly+(inequality.isEmpty()?"==":inequality)+"0,x"+(inequality.isEmpty()?"":",Reals")+")";title="解"+degree+"次"+(inequality.isEmpty()?"多项式":"不等式");}
   else{String[] vars={"x","y","z","t"};StringBuilder equations=new StringBuilder("{");for(int r=0;r<unknowns;r++){if(r>0)equations.append(',');for(int c=0;c<unknowns;c++){if(c>0)equations.append('+');equations.append('(').append(values[r][c]).append(")*").append(vars[c]);}equations.append("==(").append(values[r][unknowns]).append(')');labels.add("方程 "+(r+1));inputs.add(String.join(", ",values[r]));}expression="Solve("+equations+"},{"+String.join(",",Arrays.copyOf(vars,unknowns))+"})";title="解"+unknowns+"元方程组";}
   final String source=expression,heading=title;app.task(()->ToolInput.evaluate(app.engine,source),result->{record(heading,labels.toArray(new String[0]),inputs.toArray(new String[0]),result,result);app.view.invalidate();});
  });}
 void record(String title,String[] labels,String[] values,String source,String display){if(!flow.equals("base"))app.view.resultFeedback(true);app.previous=app.ans;app.ans=source;app.exact=source;app.view.result=display;try{JSONObject j=new JSONObject().put("source",ToolInput.readable(title,labels,values)).put("engineSource",source).put("result",source).put("displayResult",display).put("time",System.currentTimeMillis()).put("mode",title).put("toolTitle",title).put("toolLabels",new JSONArray(Arrays.asList(labels))).put("toolValues",new JSONArray(Arrays.asList(values))).put("workspaceKind",flow).put("degree",degree).put("inequality",inequality).put("unknowns",unknowns);if(flow.equals("poly")||flow.equals("system")){JSONArray data=new JSONArray();for(String[] row:app.view.grid)data.put(new JSONArray(Arrays.asList(row)));j.put("workspaceData",data);}app.tagHistory(j);app.addHistory(j);}catch(Exception ignored){}app.save();}
 boolean handle(String action){
  if(action.equals("mode")||action.equals("normal")){end();return false;}
  if(flow.equals("table")){if(action.equals("evaluate")||action.equals("workflowNext")){tableNext();return true;}if(action.equals("workflowPrevious")){tableValues[step]=app.formula.source(app.angleMode);if(step>0){step--;loadStep();}return true;}if(action.equals("workflowHelp")){app.toast("输入 f(x)、g(x)、起点、终点和步长；g(x) 可以留空。");return true;}}
  if((flow.equals("poly")||flow.equals("system"))&&app.view.gridActive){if(action.equals("more")&&flow.equals("poly")){app.workbench.commit(()->{StringBuilder source=new StringBuilder();for(int c=0;c<=degree;c++){if(c>0)source.append('+');source.append('(').append(app.view.grid[0][c]).append(")*x^").append(degree-c);}app.graphExpression(source.toString());});return true;}if(action.equals("evaluate")||action.equals("workflowNext")){solveCoefficients();return true;}if(action.equals("workflowHelp")){app.toast("使用方向键切换系数，按 = 求解。");return true;}}
  if(!app.view.baseMode)return false;
  if(action.equals("baseSettings")){ReferenceDialogs.radio(app,"位宽",new String[]{"8 bits signed","16 bits signed","32 bits signed","64 bits signed"},app.view.baseBits==8?0:app.view.baseBits==16?1:app.view.baseBits==32?2:3,i->handle("baseBits:"+new int[]{8,16,32,64}[i]));return true;}
  if(action.startsWith("baseRadix:")){int radix=Integer.parseInt(action.substring(10));try{if(!app.formula.empty()){long n=baseValue();app.formula.clear();app.formula.text(baseFormat(n,radix));}}catch(Exception ignored){}app.view.baseRadix=radix;app.prefs.edit().putInt("baseRadix",radix).apply();app.changed();if(app.formula.empty())try{app.view.result=baseFormat(Long.parseLong(app.ans),radix);}catch(Exception ignored){}app.save();app.view.invalidate();return true;}
  if(action.startsWith("baseBits:")){app.view.baseBits=Integer.parseInt(action.substring(9));app.prefs.edit().putInt("baseBits",app.view.baseBits).apply();app.changed();return true;}
  if(action.equals("evaluate")){baseCalculate();return true;}
  if(action.equals("answer")){try{app.formula.text(baseFormat(Long.parseLong(app.ans),app.view.baseRadix));app.changed();}catch(Exception e){app.error("Ans 需要整数");}return true;}
  if(action.startsWith("baseText:")){app.checkpoint();app.formula.text(action.substring(9));app.changed();return true;}
  return false;
 }
}
